            if grid[y][x] == '#':
                continue
            if y + 1 < Y and grid[y+1][x] != '#':
                dp[y][x] = (dp[y][x] + dp[y+1][x]) % MOD
            if grid[y][x] == '>':
                if x + 1 < X and grid[y][x+1] != '#' and grid[y][x+1] != '<':
                    dp[y][x] = (dp[y][x] + dp[y][x+1]) % MOD
            elif grid[y][x] == '<':
                if x - 1 >= 0 and grid[y][x-1] != '#' and grid[y][x-1] != '>':
                    dp[y][x] = (dp[y][x] + dp[y][x-1]) % MOD

    # Find the number of ways to reach the castle
    castle_x = None
    for x in range(X):
        if grid[0][x] == '@':
            castle_x = x
            break

    if castle_x is None:
        return "begin repairs"

    return dp[0][castle_x]

